import{z as l,x as p,o as s,c as A,q as e,j as o,D as t,d as i,s as n,S as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"最小割的建模","description":"","frontmatter":{"title":"最小割的建模","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/min-cut-applications.md","filePath":"cs/min-cut-applications.md","lastUpdated":1791063341000}'),d={name:"cs/min-cut-applications.md"};function B(c,a,C,_,m,h){const r=p("Mermaid");return s(),A("div",null,[a[2]||(a[2]=e('<h1 id="最小割的建模" tabindex="-1">最小割的建模 <a class="header-anchor" href="#最小割的建模" aria-label="Permalink to &quot;最小割的建模&quot;">​</a></h1><div class="epigraph"><p>把「选或不选」写成 $s$ 侧与 $t$ 侧；项之间的代价写成跨边容量，最小割给出最优划分。</p><footer>—— 据 Ford and Fulkerson, 1956；项目选择见 Picard, Maximal Closure of a Graph, 1976；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/min-cost-flow">最小费用最大流</a>给了带费用的流。许多组合划分其实<strong>不需要费用</strong>，只要 \\(s\\)–\\(t\\) 最小割。主干已证最大流 \\(=\\) 最小割。本课不重证。缺口是<strong>怎么建图</strong>：项目选择、图的闭包、二元势函数的子模特例。后课回到匹配的组合算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>顶点要分到 \\(S\\ni s\\) 或 \\(T\\ni t\\)。跨割边容量之和是代价。建模：想惩罚「\\(u\\) 在 \\(S\\)、\\(v\\) 在 \\(T\\)」就加边 \\(u\\to v\\) 容量 \\(=\\) 惩罚。想强制「\\(u\\) 在 \\(S\\) 则 \\(v\\) 在 \\(S\\)」则加无穷容量 \\(u\\to v\\)。项目选择：项目有利润（可负），有依赖「做 \\(A\\) 必须做 \\(B\\)」。把正利润连到 \\(t\\)、负利润从 \\(s\\) 连入，依赖无穷边，最小割对应最大闭包。</p><p><span class="marginnote">「最小割」可以想象成：把所有顶点分成 \\(s\\) 圈与 \\(t\\) 圈两堆，每条被拆散的边按容量收「拆散费」，总费用最低的分法就是最小割。它之所以好算，是因为最大流最小割定理保证这份最低费用恰好等于从 \\(s\\) 能推到 \\(t\\) 的最大流量，而最大流有多项式算法。</span></p><p>以两个项目的具体连边为例，看依赖与正负利润如何各就各位：</p>',7)),(s(),o(E,null,{default:t(()=>[n(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E6%BA%90%20s%22%5D%20--%3E%7C%22%E5%AE%B9%E9%87%8F%2060%EF%BC%9A%E5%88%A9%E6%B6%A6%22%7C%20A%5B%22%E9%A1%B9%E7%9B%AE%20A%22%5D%0A%20%20S%20--%3E%7C%22%E5%AE%B9%E9%87%8F%2030%EF%BC%9A%E5%88%A9%E6%B6%A6%22%7C%20B%5B%22%E9%A1%B9%E7%9B%AE%20B%22%5D%0A%20%20A%20--%3E%7C%22%E5%AE%B9%E9%87%8F%20%E2%88%9E%EF%BC%9A%E4%BE%9D%E8%B5%96%22%7C%20B%0A%20%20A%20--%3E%7C%22%E5%AE%B9%E9%87%8F%2050%EF%BC%9A%E6%88%90%E6%9C%AC%22%7C%20T%5B%22%E6%B1%87%20t%22%5D%0A%20%20B%20--%3E%7C%22%E5%AE%B9%E9%87%8F%2020%EF%BC%9A%E6%88%90%E6%9C%AC%22%7C%20T%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">数字实例：\\(A\\) 利润 \\(+60\\) 成本 \\(50\\)，\\(B\\) 利润 \\(+30\\) 成本 \\(20\\)，做 \\(A\\) 必先做 \\(B\\)。两个都做：\\(A,B\\) 留在 \\(s\\) 侧，割掉两条成本边共 \\(70\\)，净赚 \\(90-70=20\\)；都不做：割掉两条利润边共 \\(90\\)，净赚 \\(0\\)。依赖边无穷使 \\(A,B\\) 必须同侧，最小割自动比出「都做」更划算。</span></p><p>缺口是这些边的含义，不是 Dinic 实现。</p><h3 id="不是任意-0-1-规划" tabindex="-1">不是任意 0-1 规划 <a class="header-anchor" href="#不是任意-0-1-规划" aria-label="Permalink to &quot;不是任意 0-1 规划&quot;">​</a></h3><p>一般二次伪布尔优化 NP-hard。可表示成无向图割的，是子模（或正则）的那一类。无穷容量表示硬约束，数值太大要小心与真无穷的区别。不要把 TSP 的圈约束写成一张最小割就多项式——那会回到 NPC。</p><p><span class="marginnote">Picard 1976 最大闭包。图像二值分割的图割（Boykov 等）是同一语言，本课点名应用不进视觉课。后课 Hopcroft–Karp 是二分匹配的速度，不是割。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写清每个顶点属于 \\(s\\) 侧还是 \\(t\\) 侧的语义。列出硬约束（无穷边）与软代价（有限容量）。跑最大流，读残量 \\(s\\) 可达集。检查无穷边未被割。</p><p><span class="marginnote">跑完最大流后不必逐点记录归属：从 \\(s\\) 出发只沿还有剩余容量的边走，能走到的顶点就是 \\(s\\) 侧，其余全归 \\(t\\) 侧。这套「残量可达集」就是把一次最大流还原成具体划分方案的标准做法。</span></p>',8)),(s(),o(E,null,{default:t(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOD%5B%220-1%20%E5%88%92%E5%88%86%22%5D%20--%3E%20ST%5B%22s%20%E4%BE%A7%20%2F%20t%20%E4%BE%A7%22%5D%0A%20%20ST%20--%3E%20INF%5B%22%E6%97%A0%E7%A9%B7%E8%BE%B9%EF%BC%9A%E7%A1%AC%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20ST%20--%3E%20CAP%5B%22%E6%9C%89%E9%99%90%E8%BE%B9%EF%BC%9A%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20CAP%20--%3E%20CUT%5B%22%E6%9C%80%E5%B0%8F%E5%89%B2%20%3D%20%E6%9C%80%E4%BC%98%22%5D%0A%20%20INF%20--%3E%20CUT%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p>多源多汇仍用超级源汇。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>割的容量把「跨界」的惩罚加起来；最大流最小割保证这是最小惩罚。依赖边无穷则最优割不会切开它，否则容量无穷。与费用流：若目标是运输量而非划分，用上一课；若目标是划分代价，用本课。</p><p><span class="marginnote">初学者容易以为「无穷边不会被割」是某种特殊规则，其实只是算术：割的代价是所有跨割边容量之和，含一条无穷边的划分代价就是无穷，永远进不了「最小」的候选。硬约束与软代价由此统一成同一套加法。</span></p><p>不要用最小生成树的割（切分定理那条最轻边）代替 \\(s\\)–\\(t\\) 容量割。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多重标签图割（α-expansion）全文。不把线性规划对偶展开——那是单纯形单元。后课默认：能写成 \\(s\\)–\\(t\\) 割的 0-1 划分可最大流求解。下一课二分图最大匹配的 \\(O(E\\sqrt V)\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>划分代价 = 跨边容量；硬约束用无穷。</li><li>项目选择 / 最大闭包是标准模板。</li><li>一般伪布尔优化不能都化成一张割。</li><li>出处：Ford and Fulkerson, 1956；Picard, 1976。</li></ul>',9))])}const f=l(d,[["render",B]]);export{T as __pageData,f as default};
